vrml.1:
#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Scripting : 1

NavigationInfo {
  type "EXAMINE"
}

Viewpoint { }

Transform {
  rotation 0 0 1 0.3
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.8 0.5 0.2
      }
    }
    geometry Box {
      size 4 1 1
    }
  }
}

Transform {
  translation 0 2 0
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.2 0.5 0.8
      }
    }
    geometry Sphere {
      radius 0.5
    }
  }
}

DEF OUT Script {
  inputOutput SFString hist "sh=true"

  url "ecmascript:
    function initialize () {
      Browser .setBrowserOption ('StraightenHorizon', true);
      hist = 'sh=' + Browser .getBrowserOption ('StraightenHorizon');
    }
  "
}

